    const codeText = caught.code ?? "";
    if (codeText === "ENOENT") throw new Failure("OUT_DIR_MISSING", "The directory for --out does not exist.");
    if (codeText !== "EEXIST") throw new Failure("OUT_NOT_WRITABLE", "--out cannot be written.");
